"""sens — 使用中最常冒出来的那几个意图（识别灵敏度 / 诊断 / 重载）

用户口径：转写质量不好时，要能用嘴解决，而不是改文件重启。
  · sens_up        「听不清 / 声音小 / 提高灵敏度」   → ASR 前增益↑ + 起判 prob↓
  · sens_down      「太吵了 / 声音太大 / 降低灵敏度」 → ASR 前增益↓ + 起判 prob↑
  · sens_show      「灵敏度 / 当前增益 / 识别参数」   → 报当前值（不改）
  · asr_diag       「识别不准 / 总听错 / 转写有问题」 → 报当前值 + 下一步建议
  · reload_intents 「重新加载意图 / 刷新意图」        → 强制重载唯一意图清单

改动都：① 立即生效（改运行中实例的 cfg + VAD 实例）② 落盘到 profile 的 behavior
（重启后仍然是这个值）③ 返回一句人话（成功/失败都算）。
"""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
_AGENT = None

GAIN_MIN, GAIN_MAX = 60.0, 600.0
PROB_MIN, PROB_MAX = 0.25, 0.45


def set_agent(a):
    global _AGENT
    _AGENT = a


def _num(b, k, d):
    try:
        v = b.get(k)
        return float(v) if v is not None else float(d)
    except Exception:
        return float(d)


def snapshot(cfg):
    b = getattr(cfg, "behavior", {}) or {}
    try:
        from opencode_fastpath import intents as _intents
        dom = _intents.domain_of(cfg)
        smy = _intents.summary(cfg)
    except Exception:
        dom, smy = "?", ""
    return {"asr_gain_cap": _num(b, "asr_gain_cap", 200),
            "vad_prob_threshold": _num(b, "vad_prob_threshold", 0.4),
            "vad_required_hits": int(_num(b, "vad_required_hits", 2)),
            "vad_required_misses": int(_num(b, "vad_required_misses", 19)),
            "vad_max_gain": _num(b, "vad_max_gain", 60),
            "vad_target_rms": _num(b, "vad_target_rms", 0.03),
            "domain": dom, "intent_summary": smy}


def _apply(cfg, gain=None, prob=None, hits=None, vmax=None, vtgt=None):
    """写进 cfg（立即生效）+ 运行中实例（cfg 与 VAD 实例）+ profile（落盘）"""
    keys = {"asr_gain_cap": gain, "vad_prob_threshold": prob,
            "vad_required_hits": hits, "vad_max_gain": vmax, "vad_target_rms": vtgt}
    b = getattr(cfg, "behavior", None)
    if isinstance(b, dict):
        for k, v in keys.items():
            if v is not None:
                b[k] = (int(v) if k == "vad_required_hits"
                        else (round(float(v), 3) if k == "vad_target_rms" else round(float(v), 1)))
    a = _AGENT
    if a is not None:
        try:
            ab = a.cfg.behavior
            for k, v in keys.items():
                if v is not None:
                    ab[k] = v
            _seg = getattr(a, "seg", None)
            _sm = getattr(_seg, "sm", None)
            if _sm is not None:
                if prob is not None:
                    _sm.prob_threshold = round(float(prob), 3)   # 起判立即生效
                if hits is not None:
                    _sm.required_hits = int(hits)
            _pg = getattr(_seg, "gain", None)
            if _pg is not None:
                if vmax is not None:
                    _pg.max_gain = float(vmax)
                if vtgt is not None:
                    _pg.target = float(vtgt)
        except Exception:
            pass
    # 落盘（profile 的 behavior；改的是同一个文件，重启后仍在）
    try:
        p = Path(getattr(cfg, "path", "") or "")
        if p.exists():
            d = json.loads(p.read_text(encoding="utf-8"))
            for k, v in keys.items():
                if v is not None:
                    d.setdefault("behavior", {})[k] = v
            p.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass


def act_sens_up(arg, cfg, dry=False):
    s = snapshot(cfg)
    g = min(GAIN_MAX, max(GAIN_MIN, s["asr_gain_cap"] * 1.5))
    p = max(PROB_MIN, s["vad_prob_threshold"] - 0.05)
    hits = 1 if s["vad_required_hits"] > 1 else s["vad_required_hits"]
    vmax = min(120.0, max(30.0, s["vad_max_gain"] * 1.25))
    vtgt = min(0.08, max(0.02, s["vad_target_rms"] * 1.25))
    if dry:
        return True, (f"[dry] 灵敏度↑：起判 prob {s['vad_prob_threshold']:.2f}→{p:.2f}、"
                      f"hits {s['vad_required_hits']}→{hits}、VAD 增益上限 "
                      f"{s['vad_max_gain']:.0f}→{vmax:.0f}×、ASR 前增益 "
                      f"{s['asr_gain_cap']:.0f}→{g:.0f}×"), None
    _apply(cfg, gain=g, prob=p, hits=hits, vmax=vmax, vtgt=vtgt)
    return True, (f"灵敏度已提高（起判更容易触发）：prob {s['vad_prob_threshold']:.2f}→{p:.2f}、"
                  f"hits {s['vad_required_hits']}→{hits}、VAD 增益上限 {s['vad_max_gain']:.0f}→"
                  f"{vmax:.0f}×、ASR 前增益 {s['asr_gain_cap']:.0f}→{g:.0f}×（说「灵敏度」看当前值））"), \
        {"vad_prob_threshold": p, "vad_required_hits": hits,
         "vad_max_gain": vmax, "asr_gain_cap": g}


def act_sens_down(arg, cfg, dry=False):
    s = snapshot(cfg)
    g = max(GAIN_MIN, min(GAIN_MAX, s["asr_gain_cap"] / 1.5))
    p = min(0.55, s["vad_prob_threshold"] + 0.05)
    vmax = max(30.0, min(120.0, s["vad_max_gain"] / 1.25))
    vtgt = max(0.02, min(0.08, s["vad_target_rms"] / 1.25))
    if dry:
        return True, (f"[dry] 灵敏度↓：起判 prob {s['vad_prob_threshold']:.2f}→{p:.2f}、"
                      f"VAD 增益上限 {s['vad_max_gain']:.0f}→{vmax:.0f}×"), None
    _apply(cfg, gain=g, prob=p, vmax=vmax, vtgt=vtgt)
    return True, (f"灵敏度已降低（更不容易误触发）：prob {s['vad_prob_threshold']:.2f}→{p:.2f}、"
                  f"VAD 增益上限 {s['vad_max_gain']:.0f}→{vmax:.0f}×、"
                  f"ASR 前增益 {s['asr_gain_cap']:.0f}→{g:.0f}×"), \
        {"vad_prob_threshold": p, "vad_max_gain": vmax, "asr_gain_cap": g}


def act_sens_show(arg, cfg, dry=False):
    s = snapshot(cfg)
    return True, (f"当前识别参数：域={s['domain']} ｜ 起判 prob {s['vad_prob_threshold']:.2f} / "
                  f"hits {s['vad_required_hits']} / 平滑 ｜ VAD 增益上限 {s['vad_max_gain']:.0f}× "
                  f"(目标RMS {s['vad_target_rms']:.3f}) ｜ ASR 前增益 {s['asr_gain_cap']:.0f}× ｜ "
                  f"停止窗 {s['vad_required_misses']} 帧(≈{s['vad_required_misses']*32}ms)"), s


def act_asr_diag(arg, cfg, dry=False):
    s = snapshot(cfg)
    hint = []
    if s["asr_gain_cap"] < 150:
        hint.append("增益偏低 → 说「提高灵敏度」")
    if s["vad_prob_threshold"] > 0.42:
        hint.append("起判偏严 → 说「提高灵敏度」")
    if s["vad_required_misses"] < 12:
        hint.append("停止窗偏短（易被切碎）→ 说「调整静音判定」现场校准")
    if not hint:
        hint.append("参数在正常范围；若是「听不清」→ 说「提高灵敏度」；"
                    "若是被切碎 → 说「调整静音判定」现场校准")
    return True, (f"识别自检：域={s['domain']} ｜ 增益 {s['asr_gain_cap']:.0f}× ｜ "
                  f"prob {s['vad_prob_threshold']:.2f} ｜ 停止窗 {s['vad_required_misses']} 帧 ｜ "
                  + "；".join(hint)), s


def act_reload_intents(arg, cfg, dry=False):
    try:
        from opencode_fastpath import intents as _intents
        if dry:
            return True, "[dry] 重新加载意图清单", None
        _intents.load(cfg, force=True)
        s = _intents.summary(cfg)
        return True, f"意图清单已重新加载 → {s}", {"summary": s}
    except Exception as e:
        return False, f"重载意图清单失败: {type(e).__name__}: {e}", None
